from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Test valid
    try:
        ServerSentEvent(event="test_event", id="test_id", data="test_data")
        print("Valid event passed")
    except ValidationError as e:
        print(f"Valid event failed: {e}")

    # Test invalid event (newline)
    try:
        ServerSentEvent(event="test\nevent", id="test_id", data="test_data")
        print("Invalid event (LF) passed")
    except ValidationError as e:
        print(f"Invalid event (LF) failed as expected: {e}")

    # Test invalid event (carriage return)
    try:
        ServerSentEvent(event="test\revent", id="test_id", data="test_data")
        print("Invalid event (CR) passed")
    except ValidationError as e:
        print(f"Invalid event (CR) failed as expected: {e}")

    # Test invalid id (newline)
    try:
        ServerSentEvent(event="test_event", id="test\nid", data="test_data")
        print("Invalid id (LF) passed")
    except ValidationError as e:
        print(f"Invalid id (LF) failed as expected: {e}")

    # Test invalid id (carriage return)
    try:
        ServerSentEvent(event="test_event", id="test\rid", data="test_data")
        print("Invalid id (CR) passed")
    except ValidationError as e:
        print(f"Invalid id (CR) failed as expected: {e}")

    # Test invalid id (null)
    try:
        ServerSentEvent(event="test_event", id="test\0id", data="test_data")
        print("Invalid id (null) passed")
    except ValidationError as e:
        print(f"Invalid id (null) failed as expected: {e}")

    # Test valid data (newline)
    try:
        ServerSentEvent(event="test_event", id="test_id", data="test\ndata")
        print("Valid data (LF) passed")
    except ValidationError as e:
        print(f"Valid data (LF) failed: {e}")

test_sse_validation()
'
